import test from 'node:test';import assert from 'node:assert/strict';import {focusTasks} from '../implementation/focus.mjs';test('exclude completed tasks, return at most two, preserve original input',()=>{const tasks=[{id:'done',done:true},{id:'a',done:false},{id:'b',done:false},{id:'c',done:false}],before=structuredClone(tasks);assert.deepEqual(focusTasks(tasks).map(t=>t.id),['a','b']);assert.deepEqual(tasks,before);});
